func FuzzValidatedUnits(f *testing.F) {
	f.Add([]byte("split and validate"), uint8(1), false)
	f.Add(bytes.Repeat([]byte("long pattern"), 100), uint8(3), true)
	f.Fuzz(func(t *testing.T, payload []byte, chunk uint8, compressed bool) {
		if len(payload) > MaxPayloadSize {
			t.Skip()
		}
		encoded := encodedUnit(t, payload, compressed, false)
		var comp Compressor
		if compressed {
			comp = independentLZ4{}
		}
		source := &shortUnitReader{source: bytes.NewReader(encoded), chunk: int(chunk) + 1}
		r, _ := NewUnitReader(context.Background(), source, comp, UnitLimits{})
		_, out, e := r.Next()
		if e != nil || !bytes.Equal(out, payload) {
			t.Fatalf("round trip: %v", e)
		}
		if len(encoded) > HeaderSize(compressed)+4 {
			encoded[HeaderSize(compressed)] ^= 1
			r, _ = NewUnitReader(context.Background(), bytes.NewReader(encoded), comp, UnitLimits{})
			if _, out, e := r.Next(); e == nil || out != nil {
				t.Fatal("corrupt payload published")
			}
		}
	})
}

func FuzzV2StreamingValues(f *testing.F) {
	f.Add(byte(0), []byte{0, 0, 0, 1, 1}, uint8(1))
	f.Add(byte(1), StreamCell([]byte("€")), uint8(1))
	f.Add(byte(2), []byte{0, 0, 0, 4, 0, 0, 0, 0}, uint8(3))
	f.Add(byte(3), []byte{255, 255, 255, 254}, uint8(1))
	boolean, text, blob := CodecTestMust(cqltype.ScalarType(cqltype.TypeBoolean)), CodecTestMust(cqltype.ScalarType(cqltype.TypeText)), CodecTestMust(cqltype.ScalarType(cqltype.TypeBlob))
	list := CodecTestMust(cqltype.ListType(blob))
	f.Fuzz(func(t *testing.T, kind byte, data []byte, chunk uint8) {
		if len(data) > 4096 {
			return
		}
		switch kind % 4 {
		case 0:
			var value bool
			_ = StreamDecodeFixture(t, boolean, StreamBool, data, &value, int(chunk)+1)
		case 1:
			value := make([]byte, 0, 64)
			_ = StreamDecodeFixture(t, text, StreamText, data, &value, int(chunk)+1)
		case 2:
			value := make([][]byte, 8)
			for i := range value {
				value[i] = make([]byte, 0, 16)
			}
			_ = StreamDecodeFixture(t, list, StreamList(StreamBlob), data, &value, int(chunk)+1)
		case 3:
			value := StreamEncodedValue{Bytes: make([]byte, 0, 128)}
			_ = StreamDecodeFixture(t, list, StreamEncoded, data, &value, int(chunk)+1)
		}
	})
}

func FuzzV2ScalarUTF8(f *testing.F) {
	for _, seed := range []string{"", "hello", "é€😀", "\xed\xa0\x80", "\xf4\x90\x80\x80", "\xe2\x82"} {
		f.Add([]byte(seed), uint32(1))
	}
	f.Fuzz(func(t *testing.T, data []byte, splitPoint uint32) {
		split := int(uint64(splitPoint) % uint64(len(data)+1))
		decoded, err := TextCodec.Decode(ScalarReader(t, cqltype.TypeText, cqltype.Present, data[:split], data[split:]))
		if (err == nil) != utf8.Valid(data) {
			t.Fatalf("UTF-8 validation disagreed at split %d: %x", split, data)
		}
		if err == nil && decoded.String() != string(data) {
			t.Fatal("valid text bytes changed")
		}
	})
}

func FuzzV2ExclusiveIncrementalFraming(f *testing.F) {
	f.Add(byte(4), step04EncodedResponse(4, false, []byte("value")))
	f.Add(byte(5), step04EncodedResponse(5, false, []byte("value")))
	f.Add(byte(5), []byte{0, 0, 0, 0, 0, 0})
	f.Fuzz(func(t *testing.T, version byte, input []byte) {
		if len(input) > 8192 {
			t.Skip()
		}
		version = 3 + version%3
		source := &step04MemoryConn{source: bytes.NewReader(input)}
		r := step04MemoryReservation(version, nil, source)
		defer r.InternalClose(false)
		r.InternalLimits.MaxMetadataBytes = 2048
		r.InternalMetadataBudget.SetLimit(2048)
		response, err := r.InternalExchange(context.Background(), &attemptRequest{Statement: "SELECT", Consistency: One})
		if err != nil {
			if response != nil {
				response.InternalReleaseMetadata()
			}
			return
		}
		defer response.InternalReleaseMetadata()
		if err = response.InternalInstallColumns(response.InternalColumns); err != nil {
			return
		}
		plan, err := StreamRow(func(*Unit) {}).Compile(response.InternalColumns)
		if err != nil {
			return
		}
		var dst Unit
		for i := 0; i < 16; i++ {
			ok, err := decodeStreamRow(response, plan, &dst)
			if err != nil || !ok {
				return
			}
		}
	})
}

func FuzzStep07StreamExecutionBoundary(f *testing.F) {
	f.Add(runtimeRowsBody(nil, "value"), uint16(16))
	f.Add(runtimeRowsBody([]byte{}, ""), uint16(0))
	f.Add(runtimeRowsBody(nil), uint16(10))
	f.Fuzz(func(t *testing.T, body []byte, capacity uint16) {
		if len(body) > 64<<10 {
			return
		}
		frame := []byte{0x84, 0, 0, 0, 8}
		frame = binary.BigEndian.AppendUint32(frame, uint32(len(body)))
		frame = append(frame, body...)
		memory := &step04MemoryConn{source: bytes.NewReader(frame)}
		reservation := step04MemoryReservation(4, nil, memory)
		s := func() *Session {
			opaqueStorageValue := new(Session)
			return opaqueStorageValue
		}()

		reservation.InternalConn.InternalHost = func() *HostInfo {
			opaqueStorageValuex := new(HostInfo)
			implEndpoint.HostInfoData(opaqueStorageValuex).InternalHostId = UUID{15: 1}
			implEndpoint.HostInfoData(opaqueStorageValuex).InternalState = NodeUp
			return opaqueStorageValuex
		}()
		reservation.InternalConn.InternalHooks = newConnectionHooks(s)
		bound := runtimeQuery(t)
		defer bound.Close()
		ctx, cancel, request, err := admitExecution(context.Background(), s, bound, Options{})
		if err != nil {
			t.Fatal(err)
		}
		request.InternalOptions.InternalProfile.Speculation = nil
		cursor := func() *RowStream[[]byte] {
			opaqueStorageValuexx := new(RowStream[[]byte])
			implExecution.RowStreamData(opaqueStorageValuexx).InternalCtx = ctx
			implExecution.RowStreamData(opaqueStorageValuexx).InternalCancel = cancel
			implExecution.RowStreamData(opaqueStorageValuexx).InternalSession = s
			implExecution.RowStreamData(opaqueStorageValuexx).InternalRequest = request
			implExecution.RowStreamData(opaqueStorageValuexx).InternalDecoder = StreamOneColumn(StreamBlob)
			implExecution.RowStreamData(opaqueStorageValuexx).InternalReservation = reservation
			implExecution.RowStreamData(opaqueStorageValuexx).InternalHistory = pagingHistory{InternalMaxCount: 4, InternalMaxBytes: 64}
			return opaqueStorageValuexx
		}()
		implExecution.RowStreamData(cursor).InternalActive.Lock()
		err = implExecution.InternalRowStreamLoadPage(cursor)
		implExecution.RowStreamData(cursor).InternalActive.Unlock()
		if err != nil {
			implExecution.InternalRowStreamFail(cursor, err)
			implExecution.RowStreamData(cursor).InternalActive.Lock()
			implExecution.InternalRowStreamCleanup(cursor, false)
			implExecution.RowStreamData(cursor).InternalActive.Unlock()
		} else {
			dst := make([]byte, 0, int(capacity))
			for i := 0; i < 4 && cursor.NextInto(&dst); i++ {
			}
			cursor.Close()
			before := append([]byte(nil), dst...)
			if cursor.NextInto(&dst) || !bytes.Equal(before, dst) {
				t.Fatal("closed cursor touched destination")
			}
		}
		bound.Close()
		if err := bound.Wait(context.Background()); err != nil {
			t.Fatal(err)
		}
		if cursor.Info().DeliveredRows > 4 {
			t.Fatal("unbounded delivery")
		}
	})
}

func FuzzV2PagingHistoryBudgets(f *testing.F) {
	f.Add([]byte{1, 'a', 1, 'b', 1, 'a'})
	f.Add([]byte{0, 0})
	f.Fuzz(func(t *testing.T, data []byte) {
		if len(data) > 4096 {
			return
		}
		h := pagingHistory{InternalMaxCount: 16, InternalMaxBytes: 128}
		seen := make(map[string]bool)
		bytesUsed := 0
		for len(data) > 0 {
			n := int(data[0] % 17)
			data = data[1:]
			if n > len(data) {
				n = len(data)
			}
			token := append([]byte{}, data[:n]...)
			data = data[n:]
			state := model.PageStateOwned(token, 1)
			err := h.InternalAdd(state)
			if seen[string(token)] {
				if !errors.Is(err, ErrPagingNoProgress) {
					t.Fatal("duplicate", err)
				}
				continue
			}
			if len(seen) >= 16 || len(token) > 128-bytesUsed {
				if !errors.Is(err, ErrPagingStateLimit) {
					t.Fatal("budget", err)
				}
				continue
			}
			if err != nil {
				t.Fatal(err)
			}
			seen[string(token)] = true
			bytesUsed += len(token)
			if h.InternalCount != len(seen) || h.InternalBytes != int64(bytesUsed) {
				t.Fatal("history accounting")
			}
		}
	})
}

func FuzzV2PageDestinationFraming(f *testing.F) {
	f.Add([]byte{0, 0, 0, 4, 0, 0, 0, 7}, uint8(1))
	f.Add([]byte{255, 255, 255, 255}, uint8(1))
	f.Fuzz(func(t *testing.T, data []byte, count uint8) {
		if len(data) > 4096 {
			return
		}
		cols := NewColumns(ColumnSpec{Name: "value", Type: codecTestMust(ScalarType(TypeInt))})
		chain := codecTestMust(wire.NewChain(wire.Borrow(data)))
		owner := wire.NewLease(chain, nil)
		p := codecTestMust(newPage(&responsePage{InternalResponseData: responseData{Columns: cols, Rows: chain, RowCount: int32(count % 8), Owner: owner}}, OneColumn(Int32), nil))
		defer p.Close()
		dst := int32(99)
		for i := 0; i < 9; i++ {
			if !p.NextInto(&dst) {
				if dst != 0 {
					t.Fatal("failed destination not cleared")
				}
				err := p.Err()
				if p.NextInto(nil) || p.Err() != err {
					t.Fatal("terminal iterator changed")
				}
				break
			}
		}
	})
}

func FuzzStep06TabletPayload(f *testing.F) {
