	f.Add(step06Payload(h.WithVersion(7)), true)
	f.Fuzz(func(t *testing.T, data []byte, v2 bool) {
		h, err := parseTypedTabletPayload(BorrowBytes(data), "ks", "table", v2)
		if err == nil {
